  "conceptual_breadth": "Moderate",
  "logical_nesting": "Intermediate",
  "exploration": "Medium",
  "rubrics": [
    {
      "criterion": "The response includes a comparative quantitative analysis of alternative protein demand growth rates in Singapore, Thailand, and Indonesia, citing the specific CAGR or market size figures from the relevant public reports (e.g., 14% CAGR in Thailand, 81% demand in Indonesia, 77% willingness in Singapore).",
      "weight": 5,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response identifies the main retail distribution channels for plant-based meats in each target country and explains how each channel's customer base aligns with the startup's target segment (e.g., retail chains like NTUC, Lazada, and local QSR partnerships).",
      "weight": 4,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response lists and briefly describes at least two key regional competitors in each market, including their product categories and price points (e.g., Growthwell Foods, Shiok Meats, Green Butcher).",
      "weight": 4,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response specifies the regulatory approvals required for novel food products in Singapore, Thailand, and Indonesia, and explains the timeline and cost implications for each (e.g., SFA pre‑market clearance, BPOM approval, halal certification).",
      "weight": 5,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response discusses cultural dietary restrictions (e.g., halal, pork taboo, flexitarian preferences) and how they might influence product formulation or marketing messaging in each country.",
      "weight": 4,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response provides specific go‑to‑market strategies (direct‑to‑consumer, B2B partnerships, quick‑service restaurant collaborations) with actionable steps for each target country.",
      "weight": 4,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response evaluates sustainability and ESG considerations, including local sourcing benefits and potential greenwashing pitfalls, and gives recommendations on how to leverage these in branding.",
      "weight": 5,
      "axis": "Synthesis of Information"
    },
    {
      "criterion": "The response includes a risk assessment table that identifies at least three regulatory, supply chain, and market risks and quantifies their impact and likelihood.",
      "weight": 3,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response cites at least one credible source for each key data point (market size, demand trends, regulatory information) and formats the citations according to APA style.",
      "weight": 4,
      "axis": "References & Citation Quality"
    },
    {
      "criterion": "The response contains a concise executive summary that captures the main findings and recommendations in a paragraph no longer than 300 words.",
      "weight": 2,
      "axis": "Communication Quality"
    },
    {
      "criterion": "The response is structured with clear headings for each of the five required sections (demand trends, competitive landscape, cultural considerations, GTM, risks & opportunities).",
      "weight": 4,
      "axis": "Instruction Following"
    },
    {
      "criterion": "The response uses data from at least two different types of sources (market reports, consumer surveys, industry benchmarks) to support its analysis.",
      "weight": 3,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response uses consistent units and currency formatting (USD, percentages) throughout the report and explains any conversions.",
      "weight": 1,
      "axis": "Communication Quality"
    },
    {
      "criterion": "The response includes a graphic (or descriptive outline) of the ASEAN trade agreement impact on tariff barriers with a brief interpretation.",
      "weight": 2,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response clearly states the estimated cost of fulfilling regulatory approvals (e.g., Singapore SFA clearance, Indonesia BPOM and halal certification) and how it compares across countries.",
      "weight": 4,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response fails to discuss price sensitivity or distribution limitations when presenting consumer willingness data, thereby overlooking a critical market reality.",
      "weight": -4,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response includes at least one bullet point outlining a timeline for market entry steps with dates or milestone markers.",
      "weight": 3,
      "axis": "Instruction Following"
    },
    {
      "criterion": "The response makes unsupported revenue or growth claims without citing underlying data, resulting in unreliable projections.",
      "weight": -4,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response uses tables to present comparative data (pricing, market size) clearly annotated with source footnotes.",
      "weight": 2,
      "axis": "Communication Quality"
    },
    {
      "criterion": "The response references any known accelerator programs or tax incentives in each market and states how the startup could leverage them.",
      "weight": 3,
      "axis": "Explicit Criteria"
    }
  ]
}

